#define NEW new

class stringx {
    char *data;
public:
    stringx(const stringx &);
    ~stringx();
};

class FEMenuSystem;
class FEManager;

class FEMenu {
    char layout0[0x70];
public:
    FEMenu *next_sub;
    FEMenu *back;
};

class FEMultiMenu : public FEMenu {
    char layout1[0xe4];
public:
    FEMultiMenu();
    virtual ~FEMultiMenu();
    void cons(FEMenuSystem *s, FEManager *man, stringx p, stringx pf_name);
    void AddSubmenu(FEMenu *menu);
};

class PhotoSelectMenu : public FEMultiMenu {
    char layout[0x74];
    int highlightedIdx;
public:
    PhotoSelectMenu(FEMenuSystem *s, FEManager *man);
    int *GetPhotoIdx(void) { return &highlightedIdx; }
};

class PhotoSaveMenu : public FEMultiMenu {
    char layout[0x70];
    int *prevMenuPhotoIdx;
public:
    PhotoSaveMenu(FEMenuSystem *s, FEManager *man);
    void SetPrevMenuPhotoIdx(int *idx) { prevMenuPhotoIdx = idx; }
};

class PhotoDevelopMenu : public FEMultiMenu {
    char layout[0x70];
    int *whichPhotoPtr;
public:
    PhotoDevelopMenu(FEMenuSystem *s, FEManager *man);
    void SetPrevMenuPhotoIdx(int *idx) { whichPhotoPtr = idx; }
};

class PhotoFrontEnd : public FEMultiMenu {
    PhotoSelectMenu *selectMenu;
    PhotoSaveMenu *saveMenu;
    PhotoDevelopMenu *develMenu;
public:
    PhotoFrontEnd(FEMenuSystem* s, FEManager* man, stringx p, stringx pf_name);
    virtual ~PhotoFrontEnd();
};

PhotoFrontEnd::PhotoFrontEnd(FEMenuSystem* s, FEManager* man, stringx p, stringx pf_name)
{
	cons(s, man, p, pf_name);

	// Create submenus.
	selectMenu = NEW PhotoSelectMenu(s, man);
	saveMenu = NEW PhotoSaveMenu(s, man);
	develMenu = NEW PhotoDevelopMenu(s, man);
	// Add submenus.
	AddSubmenu(selectMenu);
	AddSubmenu(saveMenu);
	AddSubmenu(develMenu);

	selectMenu->next_sub = saveMenu;
	saveMenu->next_sub = develMenu;
	saveMenu->back = selectMenu;
	saveMenu->SetPrevMenuPhotoIdx(selectMenu->GetPhotoIdx());
	develMenu->SetPrevMenuPhotoIdx(selectMenu->GetPhotoIdx());
}
